import sys

def find_score_distribution(n, m):
    if m == 0:
        # If m is 0, we can simply use the first n natural numbers
        return ' '.join(map(str, range(1, n + 1)))

    # Calculate the maximum possible number of triples
    max_triples = n * (n - 1) * (n - 2) // 6

    if m > max_triples:
        return '-1'

    # Start with the first n natural numbers
    scores = list(range(1, n + 1))

    # Try to adjust the scores to get exactly m triples
    current_triples = 0
    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            target = scores[i] + scores[j]
            if target > scores[-1]:
                scores.append(target)
                current_triples += (n - j - 1)
                if current_triples >= m:
                    break
            elif target in scores[j + 1:]:
                current_triples += 1
                if current_triples >= m:
                    break
        if current_triples >= m:
            break

    if current_triples != m:
        return '-1'

    return ' '.join(map(str, scores))

# Read input
n, m = map(int, sys.stdin.read().split())

